from locust import HttpUser, between, task


class GatewayUser(HttpUser):
    wait_time = between(1, 3)

    @task(3)
    def health(self) -> None:
        self.client.get("/health")

    @task(2)
    def service_health(self) -> None:
        self.client.get("/services/health")

    @task(1)
    def create_task_workflow(self) -> None:
        self.client.post(
            "/workflow/task",
            json={
                "project_id": "PRJ-LOAD",
                "title": "Load test task",
                "description": "generated by locust",
                "priority": "medium",
                "task_tags": ["backend"],
                "story_points": 3,
                "actor_id": "PM-LOAD",
                "actor_role": "project_manager",
                "auto_assign": False,
                "notify": False,
            },
        )
